import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mul, add, texture, uniform, varying } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Color palette
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Create textured displacement plane
  const geometry = new THREE.PlaneGeometry(2.5, 0.15, 64, 64);
  const material = new MeshStandardNodeMaterial({
    side: THREE.DoubleSide,
    wireframe: false,
  });

  // Load textures asynchronously and apply
  let textureMap = null;
  let depthMap = null;

  Promise.all([
    config.imageUrl ? ctx.textureLoader.loadTexture(config.imageUrl) : null,
    config.depthMapUrl ? ctx.textureLoader.loadTexture(config.depthMapUrl) : null,
  ]).then(([texMap, depMap]) => {
    if (texMap) {
      texMap.colorSpace = THREE.SRGBColorSpace;
      textureMap = texMap;
      material.colorNode = texture(texMap);
      material.needsUpdate = true;
    }
    if (depMap) {
      depthMap = depMap;
    }
  });

  // Apply displacement via TSL
  const displacementStrength = uniform(0.02);
  const displacementNode = depthMap ? texture(depthMap) : uniform(0);

  // Vertex displacement in Z with subtle parallax feel
  const positionNode = add(
    varying(uv()),
    mul(displacementNode, displacementStrength)
  );

  material.metalness = 0.15;
  material.roughness = 0.6;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  group.add(mesh);

  // Create center jewel (accent indicator)
  const jewelGeometry = new THREE.SphereGeometry(0.08, 32, 32);
  const jewelMaterial = new THREE.MeshStandardNodeMaterial({
    color: colors.accent,
    metalness: 0.8,
    roughness: 0.2,
    emissive: colors.accent,
    emissiveIntensity: 0.8,
  });
  const jewel = new THREE.Mesh(jewelGeometry, jewelMaterial);
  jewel.position.z = 0.05;
  group.add(jewel);

  // Interaction handlers
  const handlers = {};

  let hoverTimeline = null;
  let pressTimeline = null;

  handlers.onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: 0.15,
      duration: 0.5,
      ease: 'power3.out',
    });
    gsap.to(jewel, {
      emissiveIntensity: 1.2,
      duration: 0.3,
      ease: 'power2.out',
    });
  };

  handlers.onHoverEnd = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(group.position, {
      y: 0,
      duration: 0.6,
      ease: 'power4.out',
    });
    gsap.to(jewel, {
      emissiveIntensity: 0.8,
      duration: 0.3,
      ease: 'power2.out',
    });
  };

  handlers.onClick = () => {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(
      group.scale,
      {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      },
      0
    );
    pressTimeline.to(
      group.scale,
      {
        x: 1,
        y: 1,
        duration: 0.3,
        ease: 'power2.out',
      },
      0.12
    );
    ctx.emit('hub-features.select', {});
  };

  group.userData.handlers = handlers;

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    jewelGeometry.dispose();
    jewelMaterial.dispose();
    if (textureMap) textureMap.dispose();
    if (depthMap) depthMap.dispose();
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
  };

  return group;
}
